import React, { useState } from 'react';
import { Task, DayData } from '../types';
import { useTrackerData } from '../hooks/useTrackerData';

interface CalendarViewProps {
  darkMode: boolean;
  onBack: () => void;
}

const CalendarView: React.FC<CalendarViewProps> = ({ darkMode, onBack }) => {
  const {
    calendarData,
    toggleTask,
    skipTask,
    calculateCompletionPercentage
  } = useTrackerData();

  const [selectedDay, setSelectedDay] = useState<number | null>(null);

  // Get day data or create default
  const getDayData = (day: number): DayData => {
    const existingDay = calendarData.find(d => d.day === day);
    if (existingDay) return existingDay;

    // Create default day data if not exists
    const isWeekday = new Date(2026, 3, day).getDay() >= 1 && new Date(2026, 3, day).getDay() <= 5;
    const defaultTasks: Task[] = [
      // Morning Routine
      { id: '1', category: 'Morning Routine', title: 'Wake up and freshen up', time: '6:00–6:30 AM', completed: false, skipped: false },
      { id: '2', category: 'Morning Routine', title: '10 min meditation + 10 min manifestation & gratitude', time: '6:30–6:50 AM', completed: false, skipped: false },
      { id: '3', category: 'English Learning', title: '5 new words with sentences', time: '7:00–8:15 AM', completed: false, skipped: false },
      { id: '4', category: 'English Learning', title: '10 min book reading in English', time: '7:00–8:15 AM', completed: false, skipped: false },
      { id: '5', category: 'English Learning', title: '1 YouTube lecture (finish completely)', time: '7:00–8:15 AM', completed: false, skipped: false },

      // Trading
      { id: '6', category: 'Trading', title: 'Trade planning + minimum 2–3 live trades', time: '9:00–9:40 AM', completed: false, skipped: false },
      { id: '7', category: 'Trading', title: isWeekday ? 'Trade analysis and learning (after office)' : '2 full hours of trading practice', time: isWeekday ? '7:00–7:30 PM' : 'Full session', completed: false, skipped: false },

      // Coding/DSA
      { id: '8', category: 'Coding/DSA', title: isWeekday ? 'DSA + Flutter questions (30 min)' : 'DSA practice (1 hour)', time: isWeekday ? '9:00–9:30 PM' : 'Flexible', completed: false, skipped: false },

      // Flutter/React Development
      { id: '9', category: 'Flutter/React', title: getDevelopmentTask(day), time: getDevelopmentTime(day, isWeekday), completed: false, skipped: false },

      // Night Review
      { id: '10', category: 'Night Review', title: 'Check all completed/missed tasks', time: 'Before sleep', completed: false, skipped: false },
      { id: '11', category: 'Night Review', title: 'Plan next day\'s topics', time: 'Before sleep', completed: false, skipped: false },
      { id: '12', category: 'Night Review', title: 'Write short note before sleeping', time: 'Before sleep', completed: false, skipped: false },
    ];

    return {
      day,
      date: new Date(2026, 3, day).toISOString(),
      tasks: defaultTasks,
      points: 0,
      streak: 0,
      completed: false,
      grade: 'F'
    };
  };

  const getDevelopmentTask = (day: number) => {
    if (day <= 30) return 'Flutter development session';
    return 'Flutter + React development session';
  };

  const getDevelopmentTime = (day: number, isWeekday: boolean) => {
    if (day <= 30) {
      return isWeekday ? '9:30 PM–1:00 AM (3 hrs)' : '10 hrs Flutter';
    }
    return isWeekday ? '1.5 hrs Flutter + 2 hrs React' : '5 hrs Flutter + 5 hrs React';
  };

  const getDayCompletionColor = (dayData: DayData) => {
    const completedTasks = dayData.tasks.filter(t => t.completed).length;
    const totalTasks = dayData.tasks.length;
    const percentage = (completedTasks / totalTasks) * 100;

    if (percentage === 100) return 'bg-green-600';
    if (percentage >= 75) return 'bg-blue-600';
    if (percentage >= 50) return 'bg-yellow-600';
    if (percentage >= 25) return 'bg-orange-600';
    return 'bg-red-600';
  };

  const getDayCompletionPercentage = (dayData: DayData) => {
    const completedTasks = dayData.tasks.filter(t => t.completed).length;
    const totalTasks = dayData.tasks.length;
    return Math.round((completedTasks / totalTasks) * 100);
  };

  const getDayGrade = (dayData: DayData) => {
    const completedTasks = dayData.tasks.filter(t => t.completed).length;
    const totalTasks = dayData.tasks.length;
    const percentage = (completedTasks / totalTasks) * 100;

    if (percentage >= 90) return 'A';
    if (percentage >= 80) return 'B';
    if (percentage >= 70) return 'C';
    if (percentage >= 60) return 'D';
    return 'F';
  };

  return (
    <div className={`min-h-screen ${darkMode ? 'bg-dark-primary text-dark-text' : 'bg-gray-50 text-gray-900'}`}>
      {/* Header */}
      <div className={`${darkMode ? 'bg-dark-secondary border-b border-dark-accent' : 'bg-white border-b border-gray-200'}`}>
        <div className="max-w-7xl mx-auto px-4 py-6">
          <div className="flex justify-between items-center">
            <div>
              <h1 className="text-3xl font-bold text-white">180-Day Calendar View</h1>
              <p className={darkMode ? 'text-dark-text-secondary mt-1' : 'text-gray-600 mt-1'}>
                Click any day to see and track tasks
              </p>
            </div>
            <button
              onClick={onBack}
              className="px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
            >
              Back to Dashboard
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Month Overview */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
          {Array.from({ length: 6 }, (_, monthIndex) => {
            const startDay = monthIndex * 30 + 1;
            const endDay = Math.min((monthIndex + 1) * 30, 180);
            const monthName = new Date(2026, 3 + monthIndex).toLocaleDateString('en-US', { month: 'long' });

            return (
              <div key={monthIndex} className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-6`}>
                <h3 className="text-lg font-bold text-white mb-4">{monthName}</h3>
                <div className="grid grid-cols-6 gap-2">
                  {Array.from({ length: endDay - startDay + 1 }, (_, i) => {
                    const dayNumber = startDay + i;
                    const dayData = getDayData(dayNumber);
                    const completionPercentage = getDayCompletionPercentage(dayData);
                    const completionColor = getDayCompletionColor(dayData);

                    return (
                      <button
                        key={dayNumber}
                        onClick={() => setSelectedDay(dayNumber)}
                        className={`aspect-square flex flex-col items-center justify-center rounded-lg text-xs font-medium transition-all hover:scale-105 ${
                          selectedDay === dayNumber ? 'ring-2 ring-blue-400' : ''
                        } ${darkMode ? 'hover:bg-dark-accent' : 'hover:bg-gray-100'}`}
                        title={`Day ${dayNumber}: ${completionPercentage}% complete`}
                      >
                        <div className="text-white font-bold">{dayNumber}</div>
                        {dayData && (
                          <div className={`w-2 h-2 rounded-full ${completionColor} mt-1`}></div>
                        )}
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        {/* Selected Day Detail */}
        {selectedDay && (
          <div className={`${darkMode ? 'bg-dark-secondary' : 'bg-white'} rounded-xl p-6`}>
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-bold text-white">Day {selectedDay} Tasks</h2>
              <button
                onClick={() => setSelectedDay(null)}
                className={`px-4 py-2 ${darkMode ? 'bg-dark-accent hover:bg-dark-muted' : 'bg-gray-200 hover:bg-gray-300'} rounded-lg transition-colors`}
              >
                Close
              </button>
            </div>

            {(() => {
              const dayData = getDayData(selectedDay);
              return (
                <div className="space-y-4">
                  {['Morning Routine', 'English Learning', 'Trading', 'Coding/DSA', 'Flutter/React', 'Night Review'].map(category => {
                    const categoryTasks = dayData.tasks.filter(t => t.category === category);
                    if (categoryTasks.length === 0) return null;

                    return (
                      <div key={category}>
                        <h3 className="text-lg font-semibold text-white mb-3 flex items-center">
                          <span className="w-2 h-2 bg-blue-400 rounded-full mr-2"></span>
                          {category}
                        </h3>
                        <div className="space-y-2">
                          {categoryTasks.map(task => (
                            <div key={task.id} className={`${darkMode ? 'bg-dark-primary' : 'bg-gray-50'} rounded-lg p-4 flex items-center justify-between`}>
                              <div className="flex items-center space-x-3">
                                <input
                                  type="checkbox"
                                  checked={task.completed}
                                  onChange={() => toggleTask(selectedDay, task.id)}
                                  className="w-5 h-5 text-blue-500 bg-dark-accent border-dark-muted rounded focus:ring-blue-500 focus:ring-2"
                                />
                                <div>
                                  <div className={`font-medium ${task.completed ? 'text-green-400 line-through' : 'text-white'}`}>
                                    {task.title}
                                  </div>
                                  {task.time && (
                                    <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>{task.time}</div>
                                  )}
                                </div>
                              </div>
                              <div className="flex items-center space-x-2">
                                {task.completed && (
                                  <span className="text-green-400 text-sm font-medium">Completed</span>
                                )}
                                {task.skipped && (
                                  <span className="text-yellow-400 text-sm font-medium">Skipped</span>
                                )}
                                {!task.completed && !task.skipped && (
                                  <span className={darkMode ? 'text-dark-text-secondary text-sm font-medium' : 'text-gray-500 text-sm font-medium'}>Pending</span>
                                )}
                                <button
                                  onClick={() => skipTask(selectedDay, task.id)}
                                  className={`px-3 py-1 text-xs ${darkMode ? 'bg-dark-accent hover:bg-dark-muted' : 'bg-gray-200 hover:bg-gray-300'} rounded-md transition-colors`}
                                >
                                  Skip
                                </button>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    );
                  })}

                  {/* Day Summary */}
                  <div className={`mt-6 p-4 rounded-lg ${darkMode ? 'bg-dark-primary' : 'bg-gray-50'}`}>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Completion</div>
                        <div className="text-2xl font-bold text-white">
                          {getDayCompletionPercentage(dayData)}%
                        </div>
                      </div>
                      <div>
                        <div className={`text-sm ${darkMode ? 'text-dark-text-secondary' : 'text-gray-600'}`}>Grade</div>
                        <div className={`text-2xl font-bold ${getDayGrade(dayData) === 'A' ? 'text-green-400' : 
                          getDayGrade(dayData) === 'B' ? 'text-blue-400' :
                          getDayGrade(dayData) === 'C' ? 'text-yellow-400' :
                          getDayGrade(dayData) === 'D' ? 'text-orange-400' : 'text-red-400'}`}>
                          {getDayGrade(dayData)}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })()}
          </div>
        )}
      </div>
    </div>
  );
};

export default CalendarView;
